      "\u0E42\u0E23\u0E07\u0E40\u0E23\u0E35\u0E22\u0E19\u0E40\u0E17\u0E28\u0E1A\u0E32\u0E25\u0E15\u0E49\u0E19\u0E41\u0E1A\u0E1A \u0E08.\u0E20\u0E39\u0E40\u0E01\u0E47\u0E15",
